import { DataTexture, LinearFilter, LinearMipmapLinearFilter, RGBAFormat, SRGBColorSpace } from "three";

/** Four material swatches in one 256px atlas: wood, woven bamboo, nipa, paint.
 * Generated bytes keep the same materials available in Expo GL and the PWA. */
export function createHouseSurfaceTexture() {
  const size = 256, tileSize = 128, pixels = new Uint8Array(size * size * 4);
  const random = (x: number, y: number) => {
    let n = Math.imul(x + 17, 374761393) + Math.imul(y + 31, 668265263);
    n = Math.imul(n ^ (n >>> 13), 1274126177);
    return ((n ^ (n >>> 16)) >>> 0) / 4294967296;
  };
  for (let tile = 0; tile < 4; tile++) for (let y = 0; y < tileSize; y++) for (let x = 0; x < tileSize; x++) {
    const i = ((Math.floor(tile / 2) * tileSize + y) * size + (tile % 2) * tileSize + x) * 4;
    const fine = random(x + tile * 137, y) - .5;
    let base: number[], tone: number, alpha = 255;
    if (tile === 0 || tile === 3) {
      const plank = Math.floor(x / 16), edge = x % 16;
      const grain = Math.sin(x * 2.6 + Math.sin(y * .08 + plank) * 1.3);
      const knot = Math.sin(Math.hypot((x % 16 - 7) * 1.5, (y - 38 - plank * 5) * .28) * 2.1);
      tone = fine * 7 + grain * 7 + knot * 3 + (random(plank, tile) - .5) * 18;
      if (edge === 0) tone -= 42;
      if (edge === 1) tone += 12;
      base = tile === 0 ? [156,116,76] : [186,183,166];
    } else if (tile === 1) {
      const horizontal = (Math.floor(x / 6) + Math.floor(y / 6)) % 2 === 0;
      const thread = horizontal ? y % 6 : x % 6;
      tone = fine * 6 + (thread === 0 ? -27 : thread === 1 ? 15 : 0) + (horizontal ? 5 : -5);
      base = [184,157,111];
    } else {
      const strand = Math.floor(x / 2);
      const row = (y + random(strand, 8) * 6) % 28;
      tone = (random(strand, 4) - .5) * 32 + fine * 8 + (x % 2 ? -9 : 7);
      if (row < 3) tone -= 24;
      if (row > 25) tone += 9;
      base = [139,117,77];
      // Only the thatch eave frays; all structural surfaces remain opaque.
      if (y < 3 + random(strand, 9) * 4) alpha = 0;
    }
    for (let c = 0; c < 3; c++) pixels[i + c] = Math.max(0, Math.min(255, base[c] + tone));
    pixels[i + 3] = alpha;
  }
  const map = new DataTexture(pixels, size, size, RGBAFormat);
  map.name = "Village wood, woven bamboo and nipa roof";
  map.colorSpace = SRGBColorSpace; map.magFilter = LinearFilter;
  map.minFilter = LinearMipmapLinearFilter; map.generateMipmaps = true; map.needsUpdate = true;
  return map;
}
